stops={"TAA","TAG","TGA"}
starts={"ATG","GTG","TTG","CTG"}

# Clean ORF finder: returns (strand, start1, end1, aa) in + coordinates
def orfs(s,minaa=80):
    res=[]
    ss=revcomp(s)
    for strand,cur in [("+",s),("-",ss)]:
        for f in range(3):
            pos=f
            while pos+3<=len(cur):
                if cur[pos:pos+3] in starts:
                    j=pos+3
                    while j+3<=len(cur) and cur[j:j+3] not in stops:
                        j+=3
                    aa=(j-pos)//3
                    if aa>=minaa:
                        if strand=="+":
                            res.append((strand,pos+1,j,aa))
                        else:
                            # + coords: 5' end = L-pos, 3' end = L-j+1... careful
                            # cur[pos] = seq[L-1-pos]
                            five = L-pos          # + coord of first base of codon
                            three = L-1-(j-1)     # + coord of last base (j-1 in cur)
                            res.append((strand,three,five,aa))
                    pos+=3
                else:
                    pos+=3
    return res

