def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
stops={"TAA","TAG","TGA"}

def stopfree(s):
    """return list of (start,end,frame,nt) maximal stop-free stretches, 1-based + coords"""
    res=[]
    for strand,cur in [("+",s),("-",revcomp(s))]:
        for f in range(3):
            # walk codons
            i=f
            seg_start=i
            pos=i
            while pos+3<=len(cur):
                c=cur[pos:pos+3]
                if c in stops:
                    nt=pos-seg_start
                    if nt>=300:
                        if strand=="+":
                            res.append((seg_start+1,pos,nt,strand,f))
                        else:
                            five=L-seg_start
                            three=L-1-(pos-1)
                            res.append((three,five,nt,strand,f))
                    seg_start=pos+3
                pos+=3
            # tail
            nt=len(cur)-seg_start
            if nt>=300:
                if strand=="+":
                    res.append((seg_start+1,len(cur),nt,strand,f))
                else:
                    five=L-seg_start; three=1
                    res.append((1,five,nt,strand,f))
    return res

